{"results": [{"id": "hp_doc_40d93eb2deaab949fae3d0ad1fd6a7b18c6e013c78db75ff651356eff67fa856", "title": "Vincent Castellanos", "text": "Vincent Castellanos (born August 7, 1961) is an American actor. Castellanos is best known for his role as Mateo in the adventure-horror film Anaconda.", "score": 34.5656}, {"id": "hp_doc_284be4b696c98d618c5cc6a97c33cbbcd84c81a218aeaa1264656ada3eeda6ed", "title": "Anaconda (film)", "text": "Anaconda is a 1997 adventure horror film by Peruvian director Luis Llosa, starring Jennifer Lopez, Ice Cube, Jon Voight, Eric Stoltz, Jonathan Hyde and Owen Wilson. It centers on a documentary film crew who have been taken hostage by a snake hunter who is going after the legendary giant anaconda, which is discovered in the Amazon rainforest.", "score": 13.5579}, {"id": "hp_doc_1aad1259dd117bd12510e6efc67b91577b275818d2758fb539059ace95a9a83d", "title": "Lincoln A. Castellanos", "text": "Lincoln A. Castellanos (born August 20, 1988) is an American actor perhaps best known for his work on such television series and films as \"Fear the Walking Dead\" as Tobias, \"The Mentalist\", and \"I Am Gangster\".", "score": 11.9431}], "remaining_searches": 2}
